   if strings.TrimSpace(args[prefixArgs]) == "" { return fmt.Errorf("query must not be empty") }
  }
  return nil
 }
 run := cmd.RunE
 cmd.RunE = func(cmd *cobra.Command, args []string) error {
  if cmd.Flags().Changed("query") { args = append(append([]string(nil), args...), selection.text) }
  return run(cmd, args)
 }
}
